-- Reaplica os privilégios da baseline de produção (schema lodgra_private e funções).
--
-- Motivo: o staging perdeu o GRANT USAGE ON SCHEMA lodgra_private e os REVOKE das funções
-- (drift anterior à baseline). Sem USAGE, "Guardar informação financeira" falha com
-- permission denied. Em produção o efeito líquido é nulo: os privilégios já são estes.
-- Gerado a partir de 20260925000000_baseline_producao.sql (exceto refresh_commission_summary,
-- removida em 20260927110000, e das funções da extensão http, que pertencem a supabase_admin).

-- 1. Schema lodgra_private
GRANT USAGE ON SCHEMA "lodgra_private" TO "authenticated";
GRANT USAGE ON SCHEMA "lodgra_private" TO "service_role";

-- 2. Zera grants explícitos dos papéis da API nas funções listadas na baseline
REVOKE ALL ON FUNCTION "lodgra_private"."mutate_property_payout_rule_v2"("p_property_id" "uuid", "p_expected_current_rule_id" "uuid", "p_expect_absent" boolean, "p_vigencia_inicio" "date", "p_tipo_comissao" "public"."tipo_comissao_repasse", "p_comissao_valor" numeric, "p_imposto_comissao_percentual" numeric, "p_competencia_receita" "text", "p_fluxo_financeiro" "text", "p_preset" "text", "p_despesas_repassaveis" boolean, "p_dia_fechamento" smallint, "p_componentes" "jsonb", "p_observacoes" "text") FROM "anon", "authenticated", "service_role";
